export const median=a=>{const b=[...a].sort((x,y)=>x-y),n=b.length;return n?(b[(n-1)>>1]+b[n>>1])/2:NaN};
export function ranks(a){const ix=a.map((v,i)=>({v,i})).sort((a,b)=>a.v-b.v),r=Array(a.length);for(let i=0;i<ix.length;){let j=i+1;while(j<ix.length&&ix[j].v===ix[i].v)j++;for(let k=i;k<j;k++)r[ix[k].i]=(i+j+1)/2;i=j}return r}
export function rng(seed=17421){return()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
export function shuffle(a,random){for(let i=a.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
export function bh(p){const order=p.map((v,i)=>({v,i})).sort((a,b)=>a.v-b.v),q=Array(p.length);let last=1;for(let k=p.length-1;k>=0;k--){last=Math.min(last,order[k].v*p.length/(k+1));q[order[k].i]=last}return q}
export function corr(x,y){const mx=x.reduce((a,b)=>a+b,0)/x.length,my=y.reduce((a,b)=>a+b,0)/y.length;let a=0,b=0,c=0;for(let i=0;i<x.length;i++){const u=x[i]-mx,v=y[i]-my;a+=u*v;b+=u*u;c+=v*v}return b&&c?a/Math.sqrt(b*c):0}
export function cohort(data,field,pair=null){const groups=new Map();for(const s of data.samples){if(s.match!=='exact'||s.event!=='Healthy')continue;if(!groups.has(s.subject))groups.set(s.subject,[]);groups.get(s.subject).push(s)}const categorical=['ir','sex','race','study'].includes(field);return [...groups].sort(([a],[b])=>a.localeCompare(b)).flatMap(([id,ss])=>{const val=ss[0][field];if(categorical?!(pair||(field==='ir'?['IS','IR']:field==='sex'?['F','M']:field==='study'?['HMP','HMP, Exercise']:['C','A'])).includes(val):(!val||val==='NA'||!Number.isFinite(Number(val))))return[];return[{id,value:categorical?val:Number(val),n: ss.length,values:data.taxa.map((_,i)=>median(ss.map(s=>s.values[i])))}]})}
export function analyze(data,field,prevalence=.1,permutations=4999,pair=null){const people=cohort(data,field,pair),categorical=['ir','sex','race','study'].includes(field),positive=pair?.[1]||(field==='ir'?'IR':field==='sex'?'M':field==='study'?'HMP, Exercise':'A'),negative=pair?.[0]||(field==='ir'?'IS':field==='sex'?'F':field==='study'?'HMP':'C');const n=people.length,n1=people.filter(p=>p.value===positive).length,n0=n-n1;if(n<10||(categorical&&(n1<5||n0<5)))throw Error('Too few eligible participants (minimum 10 total and 5 per comparison group).');const y=categorical?people.map(p=>+(p.value===positive)):ranks(people.map(p=>p.value));const random=rng(17421),perms=[];for(let k=0;k<permutations;k++)perms.push(shuffle([...y],random));const results=[];data.taxa.forEach((name,j)=>{const x=people.map(p=>p.values[j]),prev=x.filter(v=>v>0).length/n;if(prev<prevalence||Math.max(...x)===Math.min(...x))return;const r=ranks(x),center=n1*(n+1)/2;const statistic=yy=>categorical?r.reduce((a,v,i)=>a+v*yy[i],0)-center:corr(r,yy);const stat=statistic(y);let extreme=0;for(const yy of perms)if(Math.abs(statistic(yy))>=Math.abs(stat)-1e-12)extreme++;const effect=categorical?2*stat/(n1*n0):stat;const a=x.filter((_,i)=>y[i]===1),b=x.filter((_,i)=>y[i]===0);results.push({name,index:j,p:(extreme+1)/(permutations+1),effect,prevalence:prev,medianPositive:categorical?median(a):null,medianNegative:categorical?median(b):null,delta:categorical?(median(a)-median(b))*100:null})});const qs=bh(results.map(r=>r.p));results.forEach((r,i)=>r.q=qs[i]);results.sort((a,b)=>a.q-b.q||a.p-b.p||Math.abs(b.effect)-Math.abs(a.effect));return{people,results,field,categorical,positive,negative,n,n1,n0,permutations,prevalence,seed:17421}}
export function bootstrapDelta(a,b,reps=1999){const random=rng(997),d=[];for(let k=0;k<reps;k++)d.push((median(a.map(()=>a[Math.floor(random()*a.length)]))-median(b.map(()=>b[Math.floor(random()*b.length)])))*100);d.sort((a,b)=>a-b);return[d[Math.floor(.025*(reps-1))],d[Math.ceil(.975*(reps-1))]]}
